package yagen.waitmydawn.kb.service;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import dev.langchain4j.agent.tool.*;import dev.langchain4j.data.message.*;import dev.langchain4j.model.chat.response.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.nio.file.*;import com.fasterxml.jackson.databind.*;import yagen.waitmydawn.kb.model.*;import yagen.waitmydawn.kb.config.*;import yagen.waitmydawn.kb.agent.*;
class AgentToolLoopTest {
 @TempDir Path temp;
 @AfterEach void cleanup(){Thread.interrupted();LogSetup.shutdown();RetrievalTelemetry.end();}
 private ToolExecutionRequest call(String name,String args){return ToolExecutionRequest.builder().id(UUID.randomUUID().toString()).name(name).arguments(args).build();}
 private ChatResponse reply(ToolExecutionRequest... requests){return ChatResponse.builder().aiMessage(requests.length==0?AiMessage.from("READY"):AiMessage.from(requests)).build();}
 @Test void nativeMessagesReuseEquivalentArgumentsAndStopOnReady(){var modelCalls=new AtomicInteger();var tools=new AtomicInteger();var outcome=new AgentToolLoop().run(request->{int round=modelCalls.getAndIncrement();assertTrue(request.toolSpecifications().size()>=17);if(round==0)return reply(call("resolve_objects","{\"name\":\"stone\",\"kind\":\"ITEM\"}"));if(round==1){assertTrue(request.messages().stream().anyMatch(message->message instanceof ToolExecutionResultMessage));return reply(call("resolve_objects","{\"kind\":\"ITEM\",\"name\":\"stone\"}"));}return reply();},(name,args)->{tools.incrementAndGet();return "{\"status\":\"FOUND\"}";},"stone","fixture");assertEquals("READY",outcome.reason());assertEquals(1,tools.get());assertEquals("REUSED",outcome.events().get(1).status());}
 @Test void invalidAndOversizedCallsDoNotReachExecutorAndRoundsAreBounded(){var tools=new AtomicInteger();var result=new AgentToolLoop().run(request->reply(call("search_documents","{\"query\":42}")),(name,args)->{tools.incrementAndGet();return "{}";},"test","");assertEquals("ROUND_BUDGET",result.reason());assertEquals(0,tools.get());assertEquals(6,result.rounds());assertTrue(result.events().stream().allMatch(event->event.status().equals("ERROR")));var batch=new AgentToolLoop().run(request->reply(call("query_images","{}"),call("query_images","{}"),call("query_images","{}"),call("query_images","{}"),call("query_images","{}")),(name,args)->"{}","test","");assertEquals("TOOL_BUDGET",batch.reason());assertEquals(16,batch.events().size());}
 @Test void cancellationAndModelFailureRemainDistinct(){Thread.currentThread().interrupt();assertThrows(CancellationException.class,()->new AgentToolLoop().run(request->{throw new AssertionError();},(name,args)->"{}","test",""));Thread.interrupted();assertTrue(new AgentToolLoop().run(request->{throw new IllegalStateException("fixture");},(name,args)->"{}","test","").reason().startsWith("MODEL_ERROR"));}
 @Test void largerIndependentBatchesRunAndDynamicCoverageIsNotReused(){
  var decisions=new AtomicInteger();var statuses=new AtomicInteger();
  var outcome=new AgentToolLoop().run(request->decisions.getAndIncrement()==0?reply(call("query_task_status","{}"),call("query_task_status","{}"),call("query_task_status","{}"),call("query_task_status","{}"),call("query_task_status","{}"),call("query_task_status","{}")):reply(),(name,args)->"{\"revision\":"+statuses.incrementAndGet()+"}","test","");
  assertEquals("READY",outcome.reason());assertEquals(6,statuses.get());assertTrue(outcome.events().stream().allMatch(event->event.status().equals("OK")));
  var rounds=new AtomicInteger();var missing=new AtomicBoolean(true);
  var executor=new AgentToolLoop.Executor(){@Override public String execute(String name,JsonNode args){missing.set(false);return "evidence";}@Override public String readinessGap(){return missing.get()?"construction layout missing":null;}};
  var continued=new AgentToolLoop().run(request->switch(rounds.getAndIncrement()){case 0->reply();case 1->reply(call("search_documents","{\"query\":\"layout\"}"));default->reply();},executor,"如何建造","");
  assertEquals("READY",continued.reason());assertEquals(3,continued.rounds());
 }
 @Test void followupRejectsAnUnrelatedAttributeSubjectBeforeReadingRuntimeData()throws Exception {
  var config=AppConfig.forIsolatedRun(false);config.setDataDir(temp);var db=new DatabaseBuilder(config);db.initDatabase();
  try(var embedding=new EmbeddingService(null)){
   var llm=new RagAgentService(null){@Override public dev.langchain4j.model.chat.ChatModel getChatModel(){return null;}};var result=new QaPipeline.QaResult();result.conversationTargets.add("example:current");
   var backend=new QaAgentTurn(db,new VectorStore(db,384),new KnowledgeRetrievalService(db,embedding),new UrlAgent(llm,db,embedding),result,"介绍它们",null,null,()->{});
   var failure=assertThrows(IllegalArgumentException.class,()->backend.execute("query_attributes",new ObjectMapper().readTree("{\"id\":\"other:stale\"}")));
   assertTrue(failure.getMessage().contains("outside"));
  }finally{db.shutdown();}
 }
 @Test void evaluationBudgetStopsBeforeDispatchingAnExtraModelRequest(){var calls=new AtomicInteger();var delegate=new dev.langchain4j.model.chat.ChatModel(){@Override public ChatResponse doChat(dev.langchain4j.model.chat.request.ChatRequest request){calls.incrementAndGet();return reply();}};var model=RagAgentService.withRequestBudget(delegate,2);var request=dev.langchain4j.model.chat.request.ChatRequest.builder().messages(UserMessage.from("fixture")).build();model.chat(request);model.chat(request);assertThrows(IllegalStateException.class,()->model.chat(request));assertEquals(2,calls.get());assertSame(delegate,RagAgentService.withRequestBudget(delegate,0));}
 @Test void semanticBrewingAndTradeViewsPreserveRulesWithoutCandidateExpansion()throws Exception {
  var config=AppConfig.forIsolatedRun(false);config.setDataDir(temp);var db=new DatabaseBuilder(config);db.initDatabase();var json=new ObjectMapper();String profile="b".repeat(64);
  try(var embedding=new EmbeddingService(null)) {
   var descriptor=json.createObjectNode();for(String category:List.of("brewing","trades","potions","entity_attributes"))descriptor.with("categories").putObject(category).put("status","COMPLETE");
   try(var c=db.getConnection();var p=c.prepareStatement("INSERT INTO rag_runtime_snapshot VALUES('source',?,?)")){p.setString(1,profile);p.setString(2,descriptor.toString());p.executeUpdate();}
   var records=new ArrayList<RuntimeStructuredQuery.Row>();String[] potions={"water","awkward","strength","strong_strength"};String[] ingredients={"nether_wart","blaze_powder","glowstone_dust"};
   for(int i=0;i<3;i++){var row=json.createObjectNode().put("id","test:brew"+i).put("outputPotionId","minecraft:"+potions[i+1]);row.putObject("input").put("item","minecraft:potion").put("potionId","minecraft:"+potions[i]);row.putObject("ingredient").put("item","minecraft:"+ingredients[i]);row.putObject("output").put("item","minecraft:potion").put("potionId","minecraft:"+potions[i+1]);records.add(new RuntimeStructuredQuery.Row(new RuntimeStructuredQuery.Key("brewing","test:brew"+i),row));}
   var trade=json.createObjectNode().put("id","test:trade").put("profession","minecraft:librarian").put("level",3).put("draws",2);var entry=trade.putArray("entries").addObject().put("priceRule","formula").put("selectionProbability",2.0/3);var random=entry.putArray("randomOutputs");for(int i=0;i<100;i++)random.addObject().put("enchantment","test:e"+i).put("level",i%5+1);records.add(new RuntimeStructuredQuery.Row(new RuntimeStructuredQuery.Key("trades","test:trade"),trade));
   for(int i=0;i<6;i++){var entity=json.createObjectNode().put("id","test:mage"+i).put("attributeMapOnly",true);entity.putArray("attributes").addObject().put("attribute","minecraft:max_health").put("base",20+i).put("effective",30+i).putArray("modifiers").addObject().put("amount",10);records.add(new RuntimeStructuredQuery.Row(new RuntimeStructuredQuery.Key("entity_attributes","test:mage"+i),entity));}
   try(var c=db.getConnection();var p=c.prepareStatement("INSERT INTO rag_runtime_record VALUES(?,?,?,?)")){for(var row:records){p.setString(1,profile);p.setString(2,row.key().category());p.setString(3,row.key().id());p.setString(4,row.data().toString());p.addBatch();}p.executeBatch();}
   var llm=new RagAgentService(null){@Override public dev.langchain4j.model.chat.ChatModel getChatModel(){return null;}};var result=new QaPipeline.QaResult();var backend=new QaAgentTurn(db,new VectorStore(db,384),new KnowledgeRetrievalService(db,embedding),new UrlAgent(llm,db,embedding),result,"test",null,null,()->{});
   String brew=backend.execute("query_brewing",json.readTree("{\"id\":\"minecraft:strong_strength\"}"));assertTrue(brew.contains("nether_wart"));assertTrue(brew.contains("blaze_powder"));assertTrue(brew.contains("glowstone_dust"));assertEquals(1,json.readTree(brew).path("total").asInt());
   var filtered=json.readTree(backend.execute("query_runtime",json.readTree("{\"category\":\"brewing\",\"outputPotionId\":\"minecraft:strong_strength\"}")));assertEquals(1,filtered.path("total").asInt());
   assertTrue(backend.execute("query_runtime",json.readTree("{\"category\":\"brewing\"}")).contains("FILTER_REQUIRED"));
   var summary=json.readTree(backend.execute("query_trades",json.readTree("{\"profession\":\"minecraft:librarian\",\"level\":3}")));var view=summary.path("records").get(0).path("data").path("entries").get(0);assertEquals("formula",view.path("priceRule").asText());assertEquals(100,view.path("randomOutputs").path("count").asInt());assertEquals("/entries/0/randomOutputs",view.path("randomOutputs").path("section").asText());
   var detail=json.readTree(backend.execute("query_trades",json.readTree("{\"profession\":\"minecraft:librarian\",\"level\":3,\"section\":\"/entries/0/randomOutputs/99\"}")));assertEquals("test:e99",detail.path("records").get(0).path("data").path("enchantment").asText());
   var args=json.createObjectNode().put("category","entity_attributes").put("ids_json","[\"test:mage0\",\"test:mage1\",\"test:mage2\",\"test:mage3\",\"test:mage4\",\"test:mage5\"]");var bulk=json.readTree(backend.execute("query_objects",args));assertEquals(6,bulk.path("records").size());assertEquals(30,bulk.path("records").get(0).path("data").path("attributes").get(0).path("effective").asInt());assertTrue(bulk.toString().length()<28000);assertEquals(6,result.resolvedEntities.size());assertTrue(bulk.path("records").get(0).path("data").path("attributeMapOnly").asBoolean());
  }finally{db.shutdown();}
 }
 @Test void pipelineUsesToolsAndRendersLocalRecipeWithoutLegacyPlannerOrHttp()throws Exception {
  var fixture=new RuntimeKnowledgeStoreTest();fixture.temp=temp;Path root=fixture.fixture("export",1);var config=AppConfig.forIsolatedRun(false);config.setDataDir(temp.resolve("database"));var db=new DatabaseBuilder(config);db.initDatabase();
  try(var embedding=new EmbeddingService(null);var manager=new MultiDBManager(config.getDataDir(),db)){
   new KnowledgeBuilder(config,db,embedding).build(new BuildRequest(List.of(BuildRequest.Source.of(BuildRequest.Kind.DOCUMENT_DIRECTORY,root.toString()))),null);
   var identity=new RuntimeStructuredQuery(db,RuntimeKnowledgeStore.active(db)).environment();assertEquals("1.21.1",identity.path("minecraftVersion").asText());assertEquals("neoforge",identity.path("loader").asText());
   String id;try(var c=db.getConnection();var s=c.createStatement();var rows=s.executeQuery("SELECT output_item FROM rag_runtime_recipe WHERE output_item IS NOT NULL")){assertTrue(rows.next());id=rows.getString(1);}
   var turn=new AtomicInteger();var llm=new RagAgentService(null){@Override public boolean toolLoopAvailable(){return true;}@Override public dev.langchain4j.model.chat.ChatModel getChatModel(){return null;}@Override public ChatResponse toolChat(dev.langchain4j.model.chat.request.ChatRequest request){return turn.getAndIncrement()==0?reply(call("query_recipes","{\"id\":\""+id+"\"}")):reply();}};
   var vectors=new VectorStore(db,384);var classifier=new ClassifyAgent(llm){@Override public Classification classify(String q){throw new AssertionError("Legacy classifier");}};var entities=new EntityAgent(llm,db,embedding,vectors){@Override public EntityResolutionResult resolveEntities(String q,String context){throw new AssertionError("Legacy entity planner");}};var urls=new UrlAgent(llm,db,embedding){@Override public UrlFetchResult fetchAndRetrieve(List<EntityAgent.AliasHit> aliases,List<String> topics,List<String> queries){throw new AssertionError("Unexpected network workflow");}};
   var answer=new AnswerAgent(llm){@Override public String compose(AnswerContext context){assertFalse(context.recipeMatches().isEmpty());return "本地配方。";}};var pipeline=new QaPipeline(classifier,entities,urls,answer,llm,vectors,embedding,db,manager,config.getDataDir());var result=pipeline.process(id+"怎么合成");assertEquals("READY",result.toolTrace.reason());assertFalse(result.recipeResults.isEmpty());assertFalse(result.artifacts.pictures().isEmpty());assertEquals(0,result.metrics.httpRequestCount);assertEquals(2,turn.get());
   var knowledge=new KnowledgeRetrievalService(db,embedding,config.getDataDir());var backend=new QaAgentTurn(db,vectors,knowledge,urls,new QaPipeline.QaResult(),"test",null,null,()->{});var json=new ObjectMapper();assertThrows(IllegalArgumentException.class,()->backend.execute("supplement_web",json.readTree("{\"url\":\"https://example.com\",\"gap\":\"missing\"}")));assertThrows(IllegalArgumentException.class,()->backend.execute("query_images",json.readTree("{\"need\":\"test\"}")));
   var imageTurn=new AtomicInteger();var mediaModel=new RagAgentService(null){@Override public boolean toolLoopAvailable(){return true;}@Override public dev.langchain4j.model.chat.ChatModel getChatModel(){return null;}@Override public ChatResponse toolChat(dev.langchain4j.model.chat.request.ChatRequest request){int round=imageTurn.getAndIncrement();return round==0?reply(call("resolve_objects","{\"name\":\""+id+"\",\"kind\":\"ITEM\"}")):round==1?reply(call("query_images","{\"need\":\"exact requested state\"}")):reply();}};
   var noAnswer=new AnswerAgent(mediaModel){@Override public String compose(AnswerContext context){throw new AssertionError("Known image absence needs no answer model");}};
   var missingPipeline=new QaPipeline(new ClassifyAgent(mediaModel),new EntityAgent(mediaModel,db,embedding,vectors),new UrlAgent(mediaModel,db,embedding),noAnswer,mediaModel,vectors,embedding,db,manager,config.getDataDir());
   var absent=missingPipeline.process("展示 "+id+" custom_state=unavailable 的图片");assertEquals("LOCAL_MEDIA_LIMITATION",absent.metrics.answerGeneration);assertFalse(absent.answer.contains("READY"));assertFalse(absent.mediaWarnings.isEmpty());assertTrue(absent.artifacts.pictures().isEmpty());assertEquals(0,absent.metrics.httpRequestCount);
  }finally{db.shutdown();}
 }
}
